"""The fields of an object-typed prop where structural and checker differ. Usage: python3 -I fielddiff.py <tag> <project> <comp-substr> <prop>"""
import json, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
tag, p, comp, prop = sys.argv[1:5]
for r in json.load(open(f'{HERE}/{tag}-{p}.diff.json')):
    if comp in r['c'] and r['p'] == prop and r['cls'] != 'equal':
        s, k = r['s'], r['k']
        sf = {f['name']: f for f in s.get('fields', [])}
        kf = {f['name']: f for f in k.get('fields', [])}
        print(r['c'], 'struct-only', set(sf) - set(kf), 'checker-only', set(kf) - set(sf))
        print(' order same:', [f['name'] for f in s.get('fields', [])] == [f['name'] for f in k.get('fields', [])])
        for n in sf:
            if n in kf and sf[n] != kf[n]:
                print(' ', n, '\n    S', json.dumps(sf[n])[:300], '\n    K', json.dumps(kf[n])[:300])
        break

